    Bug 1948855 - Fix intermittent comm/calendar/test/browser/browser_localICS.js. r=freaktechnik


    I noticed a trap. waitForPopupEvent() check state, but, if you happen to listen on the wrong element,
    it the state check doesn't work, so it works only when the "popupshown" event is detected by the
    parent... IF the event didn't already take place.

    Differential Revision: https://phabricator.services.mozilla.com/D287199

diff --git a/calendar/test/ItemEditingHelpers.sys.mjs b/calendar/test/ItemEditingHelpers.sys.mjs
index 05cb6812862..29b486b8f66 100644
--- a/calendar/test/ItemEditingHelpers.sys.mjs
+++ b/calendar/test/ItemEditingHelpers.sys.mjs
@@ -666,12 +666,12 @@ export async function menulistSelect(menulist, value) {
   Assert.ok(!menulist.disabled, `menulist id=${menulist.id} should be enabled`);

   synthesizeMouseAtCenter(menulist, {}, win);
-  await BrowserTestUtils.waitForPopupEvent(menulist, "shown");
+  await BrowserTestUtils.waitForPopupEvent(menulist.menupopup, "shown");

   Assert.report(false, undefined, undefined, `menulist id=${menulist.id} shown`);

   synthesizeMouseAtCenter(menuitem, {}, win);
-  await BrowserTestUtils.waitForPopupEvent(menulist, "hidden");
+  await BrowserTestUtils.waitForPopupEvent(menulist.menupopup, "hidden");

   await new Promise(resolve => win.setTimeout(resolve));
   Assert.equal(menulist.value, value, "menulist should get correct value");
